args<-commandArgs(trailingOnly=TRUE);if(length(args)<2)stop("Usage: lasso_select.R <dev.csv> <out> [vars] [seed]");if(!requireNamespace("glmnet",quietly=TRUE)||!requireNamespace("survival",quietly=TRUE))stop("Install glmnet and survival")
d<-read.csv(args[1],check.names=FALSE);out<-args[2];vars<-if(length(args)>=3)strsplit(args[3],",",fixed=TRUE)[[1]]else setdiff(names(d),c("Time","Event"));seed<-if(length(args)>=4)as.integer(args[4])else 123L;if(any(d$Time<=0))stop("Resolve Time <= 0 before LASSO");dir.create(out,recursive=TRUE,showWarnings=FALSE)
x<-model.matrix(reformulate(vars),d)[,-1,drop=FALSE];y<-survival::Surv(d$Time,d$Event);set.seed(seed);fit<-glmnet::glmnet(x,y,family="cox",alpha=1);set.seed(seed);cv<-glmnet::cv.glmnet(x,y,family="cox",alpha=1,nfolds=10)
extract<-function(s){b<-as.matrix(coef(cv,s=s));data.frame(term=rownames(b),coefficient=as.numeric(b),selected=as.numeric(b)!=0,lambda=s)};tab<-rbind(extract("lambda.min"),extract("lambda.1se"));write.csv(tab,file.path(out,"lasso_coefficients.csv"),row.names=FALSE)
pdf(file.path(out,"lasso_coefficient_paths.pdf"),7,5);plot(fit,xvar="lambda");abline(v=log(cv$lambda.min),lty=2);dev.off();pdf(file.path(out,"lasso_cross_validation.pdf"),7,5);plot(cv);dev.off();saveRDS(list(fit=fit,cv=cv,terms=colnames(x)),file.path(out,"lasso_objects.rds"))
